exercise.solution:
def weighted_gradient(grads, counts):
     if not grads or len(grads) != len(counts):
         raise ValueError('长度不一致或无微批次')
     width = len(grads[0])
     if width == 0 or any(len(g) != width for g in grads):
         raise ValueError('梯度宽度不一致')
     if any(not isinstance(n, int) or n < 0 for n in counts):
         raise ValueError('计数应为非负整数')
     total = sum(counts)
     if total == 0:
         raise ValueError('没有有效元素')
     return [sum(g[d] * n for g, n in zip(grads, counts)) / total
             for d in range(width)]

