import torch

def accumulate_gradients(model, microbatches):
    total = sum(int(valid.sum()) for _, _, valid in microbatches)
    if total == 0:
        raise ValueError('没有有效元素')
    model.zero_grad(set_to_none=True)
    for x, y, valid in microbatches:
        error = (model(x) - y).square()
        (error[valid].sum() / total).backward()
    return total

