import math

def unscale_and_clip(scaled_grad, scale, max_norm):
    if not scaled_grad or not math.isfinite(scale) or scale <= 0:
        raise ValueError('缩放尺度必须为正数')
    if not math.isfinite(max_norm) or max_norm < 0:
        raise ValueError('阈值必须为非负数')
    if any(not math.isfinite(x) for x in scaled_grad):
        raise ValueError('梯度必须有限')
    grad = [x / scale for x in scaled_grad]
    if any(not math.isfinite(x) for x in grad):
        raise ValueError('反缩放结果超出浮点有限范围')
    norm = math.hypot(*grad)
    if not math.isfinite(norm):
        raise ValueError('梯度范数超出浮点有限范围')
    factor = min(1.0, max_norm / norm) if norm else 1.0
    return norm, [x * factor for x in grad]

