import math

def classify_records(records):
    report = {key: [] for key in ['missing_optimizer', 'no_gradient', 'nonfinite_gradient', 'zero_gradient']}
    for item in records:
        if not item['trainable']:
            continue
        name, grad = item['name'], item['grad']
        if not item['in_optimizer']:
            report['missing_optimizer'].append(name)
        if grad is None:
            report['no_gradient'].append(name)
        elif any(not math.isfinite(v) for v in grad):
            report['nonfinite_gradient'].append(name)
        elif all(v == 0 for v in grad):
            report['zero_gradient'].append(name)
    return {key: sorted(names) for key, names in report.items()}

pytorchTask.solution:
import torch

def audit_gradients(model, optimizer):
    report = {k: [] for k in ['missing_optimizer', 'no_gradient', 'nonfinite_gradient', 'zero_gradient']}
    members = {id(p) for group in optimizer.param_groups for p in group['params']}
    for name, p in model.named_parameters():
        if not p.requires_grad:
            continue
        if id(p) not in members:
            report['missing_optimizer'].append(name)
        if p.grad is None:
            report['no_gradient'].append(name)
        elif not bool(torch.isfinite(p.grad).all()):
            report['nonfinite_gradient'].append(name)
        elif bool((p.grad == 0).all()):
            report['zero_gradient'].append(name)
    return {key: sorted(names) for key, names in report.items()}

