def adam_state_bytes(total_params, trainable_params):
    if (not isinstance(total_params, int) or not isinstance(trainable_params, int)
            or total_params < 0 or trainable_params < 0 or trainable_params > total_params):
        raise ValueError('参数数量不合法')
    weights = 4 * total_params
    gradients = 4 * trainable_params
    moments = 8 * trainable_params
    return dict(weights=weights, gradients=gradients, moments=moments,
                total=weights + gradients + moments)

