import math

def gradient_relation(g_a, g_b, weight):
    if not g_a or len(g_a) != len(g_b):
        raise ValueError('向量形状不同')
    if not math.isfinite(weight) or weight < 0 or any(not math.isfinite(v) for v in g_a + g_b):
        raise ValueError('必须是有限数且权重非负')
    combined = [a + weight * b for a, b in zip(g_a, g_b)]
    if any(not math.isfinite(v) for v in combined):
        raise ValueError('合成梯度超出浮点有限范围')
    sa, sb = max(map(abs, g_a)), max(map(abs, g_b))
    if sa == 0 or sb == 0:
        return combined, None
    # 两个正尺度分别约掉，不直接计算可能溢出的 dot 或 norm 乘积。
    a, b = [v / sa for v in g_a], [v / sb for v in g_b]
    na, nb = math.hypot(*a), math.hypot(*b)
    cosine = math.fsum((u / na) * (v / nb) for u, v in zip(a, b))
    return combined, max(-1.0, min(1.0, cosine))

exercise.tests:
