assert combined == [0, 0] and cosine == -1
assert gradient_relation([1, 0], [0, 2], 2) == ([1, 4], 0.0)
assert gradient_relation([0, 0], [1, 2], 3) == ([3, 6], None)
assert gradient_relation([1, 2], [1, 2], 0)[0] == [1, 2]
for args in [([], [], 1), ([1], [1, 2], 1), ([1], [float('nan')], 1)]:
