import math
import torch

def shared_gradient_report(loss_a, loss_b, parameters, weight_b):
    params = tuple(parameters)
    if not math.isfinite(weight_b) or weight_b < 0:
        raise ValueError('任务权重必须是有限非负数')
    def read(loss):
        grads = torch.autograd.grad(loss, params, retain_graph=True, allow_unused=True)
        return torch.cat([(torch.zeros_like(p) if g is None else g).reshape(-1)
                          for p, g in zip(params, grads)])
    ga, gb = read(loss_a), read(loss_b)
    if not bool(torch.isfinite(ga).all() & torch.isfinite(gb).all()):
        raise ValueError('非有限梯度不能解释为方向')
    combined = ga + weight_b * gb
    if not bool(torch.isfinite(combined).all()):
        raise ValueError('合成梯度超出当前 dtype 的有限范围')
    sa, sb = ga.abs().max(), gb.abs().max()
    if float(sa) == 0 or float(sb) == 0:
        cosine = None
    else:
        a, b = ga / sa, gb / sb
        cosine = float(torch.dot(a / a.norm(), b / b.norm()).clamp(-1, 1))
    return dict(g_a=ga, g_b=gb, combined=combined, cosine=cosine)
